def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return max(0.0, min(budget, 18.0))

    slots = int(supply / WATER_REQ)
    if slots < 0:
        slots = 0

    pressure_bids = []
    weak_count = 0
    rich_aggressive = 0
    urgent_opp = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            pressure_bids.append(float(pbid))
        obudget = float(opp.get('budget', 0.0))
        ohp = float(opp.get('hp', 0.0))
        onw = int(opp.get('no_water_days', 0))
        if obudget < 50 or ohp <= 3:
            weak_count += 1
        if obudget >= 120 and pbid is not None and float(pbid) >= 100:
            rich_aggressive += 1
        if onw >= 2 or ohp <= 2:
            urgent_opp += 1

    highest_prev = max(pressure_bids) if pressure_bids else 0.0
    avg_prev = sum(pressure_bids) / len(pressure_bids) if pressure_bids else 0.0

    my_urgent = (no_water >= 2) or (hp <= 2)
    my_semi_urgent = (no_water >= 1) or (hp <= 4)

    if slots >= len(alive) + 1:
        bid = 8.0
    elif my_urgent:
        target = max(118.0, highest_prev + 6.0)
        if rich_aggressive >= 2:
            target = max(target, 132.0)
        bid = target
    elif slots == 0:
        bid = 0.0
    elif slots == 1:
        if rich_aggressive >= 2 and not my_semi_urgent:
            bid = 22.0
        elif highest_prev >= 140:
            bid = 26.0 if not my_semi_urgent else 108.0
        elif highest_prev >= 110:
            bid = 38.0 if not my_semi_urgent else highest_prev + 3.0
        elif highest_prev >= 80:
            bid = 52.0 if not my_semi_urgent else highest_prev + 2.0
        else:
            bid = max(48.0, avg_prev + 4.0)
    else:
        if highest_prev >= 120:
            bid = 72.0 if not my_semi_urgent else 110.0
        elif highest_prev >= 90:
            bid = 68.0
        else:
            bid = 54.0

    if weak_count >= 2 and not my_semi_urgent:
        bid -= 8.0
    if urgent_opp >= slots and my_semi_urgent:
        bid += 10.0

    if budget < 35:
        bid = min(bid, budget)
    elif budget < 80 and not my_urgent:
        bid = min(bid, 62.0)

    if hp >= 8 and no_water == 0 and rich_aggressive >= 2 and slots <= 1:
        bid = min(bid, 28.0)

    if bid < 0:
        bid = 0.0
    return max(0.0, min(float(budget), float(bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Collect yesterday bids and pressure signals
    yesterday_bids = []
    extreme_bid_bids = []
    critical_hp_opps = 0
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                bval = float(b)
                yesterday_bids.append(bval)
                if bval >= DAILY_SALARY * 1.2:
                    extreme_bid_bids.append(bval)
            except Exception:
                pass
        if int(o.get('hp', 0)) <= 1:
            critical_hp_opps += 1

    # Baseline bid: aim to secure enough water without joining extreme wars
    # If supply is higher, we can bid less; if supply is lower, bid more.
    supply_factor = 0.5
    if supply <= MIN_SUPPLY:
        supply_factor = 0.78
    elif supply >= MAX_SUPPLY:
        supply_factor = 0.45
    else:
        # linear interpolation between 0.78 at 15 and 0.45 at 25
        supply_factor = 0.78 - (supply - MIN_SUPPLY) * (0.78 - 0.45) / (MAX_SUPPLY - MIN_SUPPLY)

    # If we are in danger (many no-water days or low hp), bid more aggressively.
    danger = 0
    if hp <= 2:
        danger += 1
    if no_water_days >= 2:
        danger += 1

    # If opponent bids were extreme yesterday, they likely overcommitted. We underbid unless we must.
    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
    else:
        max_prev_bid = 0.0

    # Compute target based on signals
    if danger >= 2:
        target = DAILY_SALARY * 0.85 * supply_factor
    elif danger == 1:
        target = DAILY_SALARY * 0.65 * supply_factor
    else:
        # default: undercut extreme behavior
        if max_prev_bid >= DAILY_SALARY * 1.2:
            target = DAILY_SALARY * 0.38 * supply_factor
        else:
            target = DAILY_SALARY * 0.52 * supply_factor

    # If multiple opponents are critical, we may need to bid higher to prevent them from locking water.
    if critical_hp_opps >= 2:
        target *= 1.25

    # Cap by budget and keep some reserve for later days.
    reserve_fraction = 0.25
    max_affordable = max(0.0, budget * (1.0 - reserve_fraction))
    bid = min(target, max_affordable, budget)

    # Ensure non-negative and at least small bid if budget allows
    if bid < 0.0:
        bid = 0.0

    return float(bid)
